{
  "findings": [
    {
      "check_id": "CKV_GCP_23",
      "title": "Subnetwork lacks flow logs",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "Enabling flow logs on the subnetwork helps monitor and analyze network traffic, which is critical for detecting anomalies, troubleshooting, and ensuring compliance."
    }
  ],
  "patched_code": "resource "google_compute_subnetwork" "data_subnet" {
  name                     = "insurance-claims-processing-platform-subnet-data"
  ip_cidr_range            = "10.0.3.0/24"
  region                   = var.region
  network                  = google_compute_network.claims_vpc.id
  description              = "Data subnet for Cloud SQL database"
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}",
  "fix_summary": "Enabled flow logs for the subnetwork to improve network traffic visibility and security monitoring."
}
